fn solve(queries: Vec<(i8, i8)>) -> Vec<i8> {
    fn prefix_sum(k: i16) -> i16 {
        // S(k) for k >= 0:
        // if k even:  k/2
        // if k odd:  -(k+1)/2
        if k <= 0 {
            return 0;
        }
        if k % 2 == 0 {
            k / 2
        } else {
            -((k + 1) / 2)
        }
    }

    queries
        .into_iter()
        .map(|(l, r)| {
            // Work in i16 to avoid intermediate overflow, then cast back.
            let l16 = l as i16;
            let r16 = r as i16;
            let ans = prefix_sum(r16) - prefix_sum(l16 - 1);
            ans as i8
        })
        .collect()
}